import React, { useContext, useEffect, useState } from 'react';
import { TouchableOpacity, StyleSheet, Platform } from 'react-native';
import { NavigationContext } from '@react-navigation/native';
import Svg, { Path } from 'react-native-svg';

const BackIcon = () => (
  <Svg width="26" height="26" viewBox="0 0 24 24" fill="none">
    <Path
      d="M19 12H5M12 19L5 12L12 5"
      stroke="#ffffff"
      strokeWidth="3"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </Svg>
);

// True while this screen is the focused one in the stack (earlier screens stay mounted but hidden).
const useScreenFocused = () => {
  const navigation = useContext(NavigationContext);
  const [focused, setFocused] = useState(() => (navigation ? navigation.isFocused() : true));
  useEffect(() => {
    if (!navigation) return undefined;
    setFocused(navigation.isFocused());
    const unsubFocus = navigation.addListener('focus', () => setFocused(true));
    const unsubBlur = navigation.addListener('blur', () => setFocused(false));
    return () => {
      unsubFocus();
      unsubBlur();
    };
  }, [navigation]);
  return focused;
};

const BackButton = ({ onPress }) => {
  const focused = useScreenFocused();

  if (Platform.OS === 'web') {
    // On the website, Hose360 lives inside a clipped, scrolling box below the site header's white fade.
    // A button inside it scrolls away and ends up under the fade. So on web the button is drawn
    // straight on the page (a portal into <body>), pinned just below the header, always tappable.
    if (!focused || typeof document === 'undefined') return null;
    const { createPortal } = require('react-dom');
    return createPortal(
      <TouchableOpacity nativeID="hose-back-button" style={[styles.floatingBackButton, styles.webPinned]} onPress={onPress}>
        <BackIcon />
      </TouchableOpacity>,
      document.body
    );
  }

  return (
    <TouchableOpacity nativeID="hose-back-button" style={styles.floatingBackButton} onPress={onPress}>
      <BackIcon />
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  // Web: fixed to the viewport, just below the site header (158px tall incl. its fade), under the
  // header's own z-index (50) so menus/overlays still cover it.
  webPinned: {
    position: 'fixed',
    top: 164,
    left: 30,
    zIndex: 40,
  },
  floatingBackButton: {
    position: 'absolute',
    top: Platform.OS === 'ios' ? 60 : 20,
    left: 30,
    backgroundColor: '#4a4a4a',
    width: 68,
    height: 68,
    borderRadius: 34,
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 1.5,
    borderColor: '#4a4a4a',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 3 },
    shadowOpacity: 0.4,
    shadowRadius: 6,
    elevation: 8,
    zIndex: 1000,
  },
});

export default BackButton;
